def solve(S, p10):
    # 枚举可能的位数 d
    for d in range(1, 19):
        if S % d != 0:
            continue
        N = S // d
        # 检查 N 的十进制位数是否正好为 d
        if 1 <= N <= 10**18 and p10[d-1] <= N < p10[d]:
            return N
    return -1

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    # 预处理 10 的幂
    p10 = [1] * 19
    for i in range(1, 19):
        p10[i] = p10[i-1] * 10

    out = []
    for i in range(1, t+1):
        S = int(data[i])
        out.append(str(solve(S, p10)))
    print('\n'.join(out))

if __name__ == "__main__":
    main()
```

